longTo(editBelong.value, next);\n      upsertBelongEdge(next, id, belongTo, editState.value.trim());\n    }\n  }\n\n  next.updatedAt = new Date().toISOString();\n  store.setKnowledgeGraphWithoutHistory(next);\n  close();\n}\n</script>\n\n<style scoped>\n.item-form {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.form-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.form-label {\n  width: 42px;\n  flex-shrink: 0;\n  font-size: 12px;\n  color: var(--zn-text-muted);\n}\n.form-input {\n  flex: 1;\n  min-width: 0;\n  background: var(--zn-bg-surface2);\n  border: 1px solid var(--zn-border-light);\n  border-radius: var(--zn-radius-sm);\n  padding: 5px 9px;\n  color: var(--zn-text-primary);\n  font-size: 12px;\n}\n.form-input:focus {\n  border-color: var(--zn-accent);\n  outline: none;\n}\n.form-check {\n  cursor: pointer;\n}\n.form-checkbox {\n  accent-color: var(--zn-accent);\n}\n.form-check-text {\n  font-size: 11px;\n  color: var(--zn-text-secondary);\n}\n\n.form-btn {\n  background: var(--zn-bg-surface2);\n  border: 1px solid var(--zn-border-light);\n  border-radius: var(--zn-radius-sm);\n  color: var(--zn-text-regular);\n  padding: 4px 12px;\n  cursor: pointer;\n  font-size: 12px;\n}\n.form-btn:hover {\n  color: var(--zn-accent);\n  border-color: var(--zn-accent);\n}\n.form-btn-primary {\n  background: rgba(var(--zn-accent-rgb), 0.15);\n  border-color: var(--zn-accent);\n  color: var(--zn-accent);\n}\n.form-btn-primary:hover {\n  background: rgba(var(--zn-accent-rgb), 0.25);\n}\n</style>\n"],"sourceRoot":""}]);
